"""Offline whole-snapshot consistency verification.

``verify_snapshot(document)`` re-derives every self-contained invariant of a
persisted ledger snapshot without contacting a server or touching the
filesystem::

    {
      "state":             object (generation, optional state_root, ...),
      "chain":             non-empty block list starting at genesis,
      "pending":           mempool transaction list,
      "index":             {tx_id: confirmed_height},
      "accounts":          {account: {sent, received, transactions}},
      "audit_checkpoint":  {"event_id", "event_hash"},
      "audit_events":      optional append-only hash-chained event list,
      # trust extensions, verified when present (a pre-feature snapshot
      # omits them and is accepted as legacy):
      "trust_sources" / "allowlist" / "source_key_history",
      # extensions, accepted but not re-verified here:
      "forks" / "syncs" / "attested_syncs",
    }

Verification recomputes, from the raw JSON values:

* every transaction's canonical ``tx_id`` and Ed25519 signature;
* every block's ascending tx_id order, Merkle root and block hash, the
  consecutive heights and ``prev_hash`` linkage back to the all-zero anchor,
  the confirmed/empty genesis rules and the pending-only-at-tip rule;
* mempool uniqueness and the mempool/chain de-duplication;
* the confirmed-only transaction ``index`` and ``accounts`` activity;
* the confirmed-account Merkle ``state_root`` (using ``state.initial_balance``
  when recorded, else the default endowment);
* when ``audit_events`` is present, its dense event ids and SHA-256 hash links
  plus the ``audit_checkpoint`` pinning the log head (an absent event list
  still requires the empty-log checkpoint ``{0, "0"*64}``);
* when the trust extensions are present: ``trust_sources`` as a
  source-ascending unique array of ``{source, public_key, expires_at,
  version, status}`` records (64-char lowercase hex key, non-boolean integer
  expiry, positive integer version, ``active``/``revoked`` status),
  ``allowlist`` as a ``source -> non-boolean integer expires_at`` object, and
  ``source_key_history`` as ``{source, keys}`` items whose
  ``{version, public_key, activated_event_id}`` keys are dense from version 1
  with strictly ascending activation ids — bidirectionally consistent with
  the trust registry's latest version/public key and with the audit log's
  source-key lifecycle events (``source_registered`` opens version 1,
  ``source_rotated`` increments it, ``source_revoked`` adds none).

Two failure categories are returned, never raised:

* ``input`` — the document is not an object, a required section is missing or
  has the wrong JSON type, an unknown top-level key appears, or a field carries
  a non-integer/non-string value of the wrong kind before any recomputation;
* ``integrity`` — the document parses but a recomputed value disagrees with
  the stored one (tx/merkle/block hashes, linkage, index, accounts, state_root,
  pending uniqueness or the audit chain/checkpoint), or the trust extensions
  disagree among themselves, the registry or the audit event log.
"""
from __future__ import annotations

from . import audit
from . import crypto
from .models import (
    STATUS_CONFIRMED,
    STATUS_PENDING,
    Block,
    Transaction,
    compute_block_hash,
)
from .store import (
    DEFAULT_INITIAL_BALANCE,
    EVENT_SOURCE_REGISTERED,
    EVENT_SOURCE_REVOKED,
    EVENT_SOURCE_ROTATED,
    GENESIS_PREV_HASH,
    TRUST_ACTIVE,
    TRUST_REVOKED,
    LedgerStore,
)

# Public error categories.
ERR_INPUT = "input"
ERR_INTEGRITY = "integrity"

# Required top-level sections; every one must be present with the right type.
REQUIRED_SECTIONS = ("state", "chain", "pending", "index", "accounts", "audit_checkpoint")

# Sections a snapshot may additionally carry. forks/syncs/attested_syncs are
# durable state but their own invariants are not part of this self-contained
# check; audit_events is optional because a pre-audit-chain snapshot omits it;
# the trust extensions are optional because a pre-feature snapshot omits them
# (each is strictly verified when present).
KNOWN_OPTIONAL_SECTIONS = (
    "audit_events",
    "forks",
    "syncs",
    "attested_syncs",
    "trust_sources",
    "allowlist",
    "source_key_history",
)

# Raw keys every stored block document must carry ("status" defaults to
# confirmed for legacy snapshots).
_BLOCK_KEYS = ("height", "prev_hash", "merkle_root", "block_hash", "transactions")

# Raw keys every stored transaction document must carry.
_TX_KEYS = ("from", "to", "amount", "signature", "tx_id")

# Exact key sets of the trust extension records.
_TRUST_SOURCE_KEYS = ("source", "public_key", "expires_at", "version", "status")
_TRUST_STATUSES = (TRUST_ACTIVE, TRUST_REVOKED)
_HISTORY_ITEM_KEYS = ("source", "keys")
_HISTORY_KEY_KEYS = ("version", "public_key", "activated_event_id")

# Audit event kinds reconstructing a source's key history.
_SOURCE_KEY_EVENT_KINDS = (
    EVENT_SOURCE_REGISTERED,
    EVENT_SOURCE_ROTATED,
    EVENT_SOURCE_REVOKED,
)


class _Failure(Exception):
    """Internal control-flow exception carrying the public error category."""

    def __init__(self, category: str) -> None:
        self.category = category
        super().__init__(category)


def _is_int(value: object) -> bool:
    """Plain integer test; booleans are rejected (bool subclasses int)."""
    return isinstance(value, int) and not isinstance(value, bool)


def _failed(category: str) -> dict:
    return {
        "ok": False,
        "error": category,
        "generation": None,
        "height": None,
        "tip_hash": None,
        "state_root": None,
        "audit_checkpoint": None,
    }


def verify_snapshot(document: object) -> dict:
    """Verify the internal consistency of one decoded snapshot document.

    Returns ``{"ok": True, "error": None, "generation", "height", "tip_hash",
    "state_root", "audit_checkpoint"}`` on success, or the same shape with
    ``ok`` False, ``error`` set to ``"input"``/``"integrity"`` and every other
    field null. Never raises for malformed input.
    """
    try:
        if not isinstance(document, dict):
            raise _Failure(ERR_INPUT)
        result = _verify(document)
    except _Failure as failure:
        return _failed(failure.category)
    except Exception:
        # Defensive: structurally unforeseeable inputs report rather than crash.
        return _failed(ERR_INPUT)
    return {
        "ok": True,
        "error": None,
        "generation": result["generation"],
        "height": result["height"],
        "tip_hash": result["tip_hash"],
        "state_root": result["state_root"],
        "audit_checkpoint": result["audit_checkpoint"],
    }


def _verify(data: dict) -> dict:
    # Unknown top-level keys make the document shape wrong; the five
    # extension sections plus the optional audit log are the only extras.
    allowed = set(REQUIRED_SECTIONS) | set(KNOWN_OPTIONAL_SECTIONS)
    for key in data:
        if key not in allowed:
            raise _Failure(ERR_INPUT)
    for section in REQUIRED_SECTIONS:
        if section not in data:
            raise _Failure(ERR_INPUT)

    state = data["state"]
    chain_raw = data["chain"]
    pending_raw = data["pending"]
    index_raw = data["index"]
    accounts_raw = data["accounts"]
    checkpoint_raw = data["audit_checkpoint"]

    # -- core section types --------------------------------------------------
    if not isinstance(state, dict):
        raise _Failure(ERR_INPUT)
    if not isinstance(chain_raw, list) or not chain_raw:
        raise _Failure(ERR_INPUT)
    if not isinstance(pending_raw, list):
        raise _Failure(ERR_INPUT)
    if not isinstance(index_raw, dict):
        raise _Failure(ERR_INPUT)
    if not isinstance(accounts_raw, dict):
        raise _Failure(ERR_INPUT)

    generation = state.get("generation", 0)
    if not _is_int(generation) or generation < 0:
        raise _Failure(ERR_INPUT)
    endowment = state.get("initial_balance")
    if endowment is not None and (
        not _is_int(endowment) or endowment <= 0
    ):
        raise _Failure(ERR_INPUT)
    if endowment is None:
        endowment = DEFAULT_INITIAL_BALANCE
    recorded_state_root = state.get("state_root")
    if recorded_state_root is not None and not isinstance(recorded_state_root, str):
        raise _Failure(ERR_INPUT)

    # -- chain recomputation -------------------------------------------------
    blocks, seen_tx_ids = _recompute_chain(chain_raw)

    # -- mempool --------------------------------------------------------------
    _verify_pending(pending_raw, seen_tx_ids)

    tip = blocks[-1]
    if state.get("height") is not None and state["height"] != tip.height:
        raise _Failure(ERR_INTEGRITY)
    if state.get("tip_hash") is not None and state["tip_hash"] != tip.block_hash:
        raise _Failure(ERR_INTEGRITY)
    if (
        state.get("tip_status") is not None
        and state["tip_status"] != tip.status
    ):
        raise _Failure(ERR_INTEGRITY)

    # -- derived index / accounts / state root -------------------------------
    expected_index, expected_accounts = _compute_derived(blocks)
    _verify_index(index_raw, expected_index)
    _verify_accounts(accounts_raw, expected_accounts)

    leaves = [
        crypto.account_state_leaf(account, balance, transactions)
        for account, balance, transactions in LedgerStore.account_state_rows(
            blocks, endowment
        )
    ]
    state_root = crypto.account_state_root(leaves)
    if recorded_state_root is not None:
        # A non-string was an input error above; a wrong-length/non-hex string
        # or a digest mismatch is corruption of the stored artifact.
        if not crypto.is_hex64(recorded_state_root) or recorded_state_root != state_root:
            raise _Failure(ERR_INTEGRITY)

    # -- audit hash chain and checkpoint -------------------------------------
    checkpoint, events = _verify_audit(data.get("audit_events"), checkpoint_raw)

    # -- trust extensions (registry, allowlist, key history) ------------------
    _verify_trust(
        data.get("trust_sources"),
        data.get("allowlist"),
        data.get("source_key_history"),
        events,
    )

    return {
        "generation": generation,
        "height": tip.height,
        "tip_hash": tip.block_hash,
        "state_root": state_root,
        "audit_checkpoint": checkpoint,
    }


def _recompute_chain(chain_raw: list) -> tuple[list[Block], set[str]]:
    """Parse and re-verify the canonical chain straight from the raw JSON.

    Field presence/type defects are input errors; every recomputed mismatch
    (heights, prev_hash links, tx_ids, signatures, ordering, Merkle roots,
    block hashes, genesis/pending-status rules) is an integrity error.
    """
    blocks: list[Block] = []
    seen_tx_ids: set[str] = set()
    for position, block_raw in enumerate(chain_raw):
        if not isinstance(block_raw, dict):
            raise _Failure(ERR_INPUT)
        for key in _BLOCK_KEYS:
            if key not in block_raw:
                raise _Failure(ERR_INPUT)
        height = block_raw["height"]
        prev_hash = block_raw["prev_hash"]
        merkle_root = block_raw["merkle_root"]
        block_hash = block_raw["block_hash"]
        txs_raw = block_raw["transactions"]
        status = block_raw.get("status", STATUS_CONFIRMED)
        # Raw types are checked before any use: a string/float/bool height or
        # amount is never coerced into the integer it resembles.
        if not _is_int(height) or height < 0:
            raise _Failure(ERR_INPUT)
        if not isinstance(prev_hash, str):
            raise _Failure(ERR_INPUT)
        if not isinstance(merkle_root, str) or not isinstance(block_hash, str):
            raise _Failure(ERR_INPUT)
        if not isinstance(txs_raw, list):
            raise _Failure(ERR_INPUT)
        if not isinstance(status, str):
            raise _Failure(ERR_INPUT)
        if status not in (STATUS_PENDING, STATUS_CONFIRMED):
            raise _Failure(ERR_INTEGRITY)

        if height != position:
            raise _Failure(ERR_INTEGRITY)
        expected_prev = (
            GENESIS_PREV_HASH if position == 0 else blocks[position - 1].block_hash
        )
        if prev_hash != expected_prev:
            raise _Failure(ERR_INTEGRITY)
        if position == 0 and (
            status != STATUS_CONFIRMED or txs_raw
        ):
            # Genesis is born confirmed and carries no transactions.
            raise _Failure(ERR_INTEGRITY)
        if position < len(chain_raw) - 1 and status == STATUS_PENDING:
            # Pending blocks may only sit at the chain tip.
            raise _Failure(ERR_INTEGRITY)

        tx_ids: list[str] = []
        for tx_raw in txs_raw:
            tx = _parse_transaction(tx_raw)
            if tx.tx_id in seen_tx_ids:
                raise _Failure(ERR_INTEGRITY)
            seen_tx_ids.add(tx.tx_id)
            tx_ids.append(tx.tx_id)

        if tx_ids != sorted(tx_ids):
            raise _Failure(ERR_INTEGRITY)
        if crypto.merkle_root(tx_ids) != merkle_root:
            raise _Failure(ERR_INTEGRITY)
        if compute_block_hash(height, prev_hash, merkle_root) != block_hash:
            raise _Failure(ERR_INTEGRITY)
        try:
            blocks.append(Block.from_dict(block_raw))
        except (KeyError, TypeError, ValueError):
            # Every field was validated above; reaching here still means the
            # stored block document cannot represent the recomputed block.
            raise _Failure(ERR_INTEGRITY) from None
    return blocks, seen_tx_ids


def _parse_transaction(tx_raw: object) -> Transaction:
    """Validate one raw transaction document and recompute tx_id/signature.

    Missing keys or non-plain-integer/non-string field types (including a
    non-positive amount) are input errors; a recomputed tx_id or Ed25519
    signature mismatch is an integrity error.
    """
    if not isinstance(tx_raw, dict):
        raise _Failure(ERR_INPUT)
    for key in _TX_KEYS:
        if key not in tx_raw:
            raise _Failure(ERR_INPUT)
    sender = tx_raw["from"]
    recipient = tx_raw["to"]
    amount = tx_raw["amount"]
    signature = tx_raw["signature"]
    stored_tx_id = tx_raw["tx_id"]
    if not isinstance(sender, str) or not isinstance(recipient, str):
        raise _Failure(ERR_INPUT)
    if not _is_int(amount) or amount <= 0:
        raise _Failure(ERR_INPUT)
    if not isinstance(signature, str) or not isinstance(stored_tx_id, str):
        raise _Failure(ERR_INPUT)
    try:
        tx = Transaction.from_dict(tx_raw)
    except (KeyError, TypeError, ValueError):
        raise _Failure(ERR_INPUT) from None
    if stored_tx_id != tx.tx_id or not crypto.is_hex64(stored_tx_id):
        raise _Failure(ERR_INTEGRITY)
    if not crypto.verify_signature(tx.sender, tx.message, tx.signature):
        raise _Failure(ERR_INTEGRITY)
    return tx


def _verify_pending(pending_raw: list, chain_tx_ids: set[str]) -> None:
    """Mempool entries are well-formed, unique, and disjoint from the chain."""
    pending: set[str] = set()
    for tx_raw in pending_raw:
        tx = _parse_transaction(tx_raw)
        if tx.tx_id in pending:
            # Duplicate pending transaction in the mempool.
            raise _Failure(ERR_INTEGRITY)
        if tx.tx_id in chain_tx_ids:
            # A mempool transaction already sealed into a block.
            raise _Failure(ERR_INTEGRITY)
        pending.add(tx.tx_id)


def _compute_derived(
    blocks: list[Block],
) -> tuple[dict[str, int], dict[str, dict]]:
    """Confirmed-only tx_id -> height index and per-account activity.

    Mirrors ``LedgerStore._compute_derived`` exactly (including a self-send
    listing its tx_id once per side) so the comparison can never disagree on
    an artifact the node itself wrote.
    """
    tx_index: dict[str, int] = {}
    accounts: dict[str, dict] = {}
    for block in blocks:
        if block.status != STATUS_CONFIRMED:
            continue
        for tx in block.transactions:
            tx_index[tx.tx_id] = block.height
            for account in (tx.sender, tx.recipient):
                entry = accounts.setdefault(
                    account, {"sent": 0, "received": 0, "transactions": []}
                )
                entry["transactions"].append(tx.tx_id)
            accounts[tx.sender]["sent"] += tx.amount
            accounts[tx.recipient]["received"] += tx.amount
    return tx_index, accounts


def _verify_index(raw: dict, expected: dict[str, int]) -> None:
    for key, value in raw.items():
        if not isinstance(key, str) or not _is_int(value) or value < 0:
            raise _Failure(ERR_INPUT)
    if raw != expected:
        # Any extra, missing or remapped confirmed-transaction entry is a
        # derived-data inconsistency.
        raise _Failure(ERR_INTEGRITY)


def _verify_accounts(raw: dict, expected: dict[str, dict]) -> None:
    for account, entry in raw.items():
        if not isinstance(account, str) or not isinstance(entry, dict):
            raise _Failure(ERR_INPUT)
        sent = entry.get("sent")
        received = entry.get("received")
        transactions = entry.get("transactions")
        if not _is_int(sent) or not _is_int(received) or not isinstance(transactions, list):
            raise _Failure(ERR_INPUT)
        if any(not isinstance(tx_id, str) for tx_id in transactions):
            raise _Failure(ERR_INPUT)
    if raw != expected:
        raise _Failure(ERR_INTEGRITY)


def _verify_audit(events_raw: object, checkpoint_raw: object) -> tuple[dict, list[dict]]:
    """Validate the optional event hash chain and the mandatory checkpoint.

    A present ``audit_events`` section must be a list of objects whose dense
    1..N ids, prev_hash links and event_hash digests all recompute; the
    checkpoint (required even with no event list) must pin the recomputed log
    head, or the all-zero root for an empty log. Chain/checkpoint defects are
    integrity errors; the section/value types are input errors. Returns the
    checkpoint summary and the validated event list (empty when the section
    is absent) for the trust cross-checks.
    """
    if events_raw is None:
        events: list[dict] = []
    else:
        if not isinstance(events_raw, list):
            raise _Failure(ERR_INPUT)
        if any(not isinstance(event, dict) for event in events_raw):
            raise _Failure(ERR_INPUT)
        events = events_raw
        try:
            audit.validate_event_chain(events)
        except audit.AuditChainError:
            raise _Failure(ERR_INTEGRITY) from None

    if not isinstance(checkpoint_raw, dict):
        raise _Failure(ERR_INPUT)
    if set(checkpoint_raw) != {"event_id", "event_hash"}:
        # The checkpoint is exactly {event_id, event_hash}; any extra or
        # missing key makes its shape wrong.
        raise _Failure(ERR_INPUT)
    event_id = checkpoint_raw["event_id"]
    event_hash_value = checkpoint_raw["event_hash"]
    if not _is_int(event_id) or event_id < 0:
        raise _Failure(ERR_INPUT)
    if not isinstance(event_hash_value, str):
        raise _Failure(ERR_INPUT)
    try:
        audit.validate_checkpoint(checkpoint_raw, events)
    except audit.AuditChainError:
        raise _Failure(ERR_INTEGRITY) from None
    return {"event_id": event_id, "event_hash": event_hash_value}, events


def _verify_trust(
    trust_raw: object,
    allowlist_raw: object,
    history_raw: object,
    events: list[dict],
) -> None:
    """Validate the trust extension sections against each other and the log.

    Every section is optional (a pre-feature snapshot omits them); a present
    section is strictly validated. Field presence and raw JSON types are input
    errors; value-format, ordering and uniqueness defects, and any
    disagreement between the key history, the trust registry and the audit
    log's source-key lifecycle events, are integrity errors.
    """
    registry = _parse_trust_sources(trust_raw)
    _parse_allowlist(allowlist_raw)
    if history_raw is None:
        # Legacy snapshot without the section: the registry and allowlist
        # checks above still apply, but there is no persisted history to
        # cross-check against the registry and the event log.
        return
    history = _parse_source_key_history(history_raw)
    expected = _reconstruct_key_history(registry, events)
    for source, entries in history.items():
        if source not in registry:
            # A history item whose source is absent from the registry is
            # orphan data; the persisted sections must agree bidirectionally.
            raise _Failure(ERR_INTEGRITY)
        if entries != expected[source]:
            raise _Failure(ERR_INTEGRITY)
    for source in registry:
        if source not in history:
            # Current snapshots write one history item per registered source.
            raise _Failure(ERR_INTEGRITY)


def _parse_trust_sources(raw: object) -> dict[str, dict]:
    """Validate the persisted source-trust registry as a raw JSON array.

    The array must be sorted by source with no duplicates; each record
    carries exactly ``{source, public_key, expires_at, version, status}``.
    """
    if raw is None:
        return {}
    if not isinstance(raw, list):
        raise _Failure(ERR_INPUT)
    registry: dict[str, dict] = {}
    previous: str | None = None
    for entry in raw:
        if not isinstance(entry, dict):
            raise _Failure(ERR_INPUT)
        if set(entry) != set(_TRUST_SOURCE_KEYS):
            raise _Failure(ERR_INPUT)
        source = entry["source"]
        public_key = entry["public_key"]
        expires_at = entry["expires_at"]
        version = entry["version"]
        status = entry["status"]
        if not isinstance(source, str) or not source:
            raise _Failure(ERR_INPUT)
        if not isinstance(public_key, str):
            raise _Failure(ERR_INPUT)
        if not _is_int(expires_at):
            raise _Failure(ERR_INPUT)
        if not _is_int(version) or version < 1:
            raise _Failure(ERR_INPUT)
        if not isinstance(status, str):
            raise _Failure(ERR_INPUT)
        if not crypto.is_hex64(public_key):
            raise _Failure(ERR_INTEGRITY)
        if status not in _TRUST_STATUSES:
            raise _Failure(ERR_INTEGRITY)
        if previous is not None and source <= previous:
            # Sources must be unique and strictly ascending.
            raise _Failure(ERR_INTEGRITY)
        previous = source
        registry[source] = {
            "public_key": public_key,
            "expires_at": expires_at,
            "version": version,
            "status": status,
        }
    return registry


def _parse_allowlist(raw: object) -> None:
    """Validate the keyless ``{source: expires_at}`` allowlist object."""
    if raw is None:
        return
    if not isinstance(raw, dict):
        raise _Failure(ERR_INPUT)
    for source, expires_at in raw.items():
        if not isinstance(source, str) or not source:
            raise _Failure(ERR_INPUT)
        if not _is_int(expires_at):
            raise _Failure(ERR_INPUT)


def _parse_source_key_history(raw: object) -> dict[str, list[dict]]:
    """Validate the persisted per-source key history structurally.

    Each item is exactly ``{source, keys}`` with a non-empty ``keys`` list of
    ``{version, public_key, activated_event_id}`` entries whose versions are
    dense from 1 and whose activation ids strictly ascend.
    """
    if not isinstance(raw, list):
        raise _Failure(ERR_INPUT)
    history: dict[str, list[dict]] = {}
    for item in raw:
        if not isinstance(item, dict):
            raise _Failure(ERR_INPUT)
        if set(item) != set(_HISTORY_ITEM_KEYS):
            raise _Failure(ERR_INPUT)
        source = item["source"]
        keys = item["keys"]
        if not isinstance(source, str) or not source:
            raise _Failure(ERR_INPUT)
        if not isinstance(keys, list) or not keys:
            raise _Failure(ERR_INPUT)
        if source in history:
            raise _Failure(ERR_INTEGRITY)
        entries: list[dict] = []
        for position, entry in enumerate(keys):
            if not isinstance(entry, dict) or set(entry) != set(_HISTORY_KEY_KEYS):
                raise _Failure(ERR_INPUT)
            version = entry["version"]
            public_key = entry["public_key"]
            activated = entry["activated_event_id"]
            if not _is_int(version) or version < 1:
                raise _Failure(ERR_INPUT)
            if not isinstance(public_key, str):
                raise _Failure(ERR_INPUT)
            if not _is_int(activated) or activated < 0:
                raise _Failure(ERR_INPUT)
            if not crypto.is_hex64(public_key):
                raise _Failure(ERR_INTEGRITY)
            if version != position + 1:
                # Key versions are dense from 1.
                raise _Failure(ERR_INTEGRITY)
            if position > 0 and activated <= entries[-1]["activated_event_id"]:
                # Activation event ids strictly ascend with the version.
                raise _Failure(ERR_INTEGRITY)
            entries.append(
                {
                    "version": version,
                    "public_key": public_key,
                    "activated_event_id": activated,
                }
            )
        history[source] = entries
    return history


def _reconstruct_key_history(
    registry: dict[str, dict], events: list[dict]
) -> dict[str, list[dict]]:
    """Rebuild every registry source's expected key history from the log.

    Mirrors ``LedgerStore._reconstruct_source_key_history``: version 1 is
    activated by the source's ``source_registered`` event, each later version
    by the matching ``source_rotated`` event, and a ``source_revoked`` event
    references the current key without adding one. Any malformed lifecycle
    payload, version gap, rotation after revocation or registry/event
    disagreement is an integrity error. Lifecycle events for sources absent
    from the registry belong to no reconstructed history and are ignored.
    """
    reconstructed: dict[str, list[dict]] = {}
    for source, record in registry.items():
        entries: list[dict] = []
        revoked = False
        next_version = 1
        for event in events:
            kind = event.get("kind")
            if kind not in _SOURCE_KEY_EVENT_KINDS:
                continue
            if event.get("source") != source:
                continue
            event_id = event.get("event_id")
            public_key = event.get("public_key")
            expires_at = event.get("expires_at")
            version = event.get("version")
            if (
                not crypto.is_hex64(public_key)
                or not _is_int(expires_at)
                or not _is_int(version)
                or version < 1
                or not _is_int(event_id)
                or event_id < 1
            ):
                raise _Failure(ERR_INTEGRITY)
            if kind == EVENT_SOURCE_REGISTERED:
                if entries or version != 1:
                    # The history opens with a single version-1 registration.
                    raise _Failure(ERR_INTEGRITY)
                entries.append(
                    {
                        "version": 1,
                        "public_key": public_key,
                        "activated_event_id": event_id,
                    }
                )
                next_version = 2
            elif kind == EVENT_SOURCE_ROTATED:
                if revoked or not entries or version != next_version:
                    # Rotations increment the version one step at a time and
                    # never happen after revocation.
                    raise _Failure(ERR_INTEGRITY)
                entries.append(
                    {
                        "version": version,
                        "public_key": public_key,
                        "activated_event_id": event_id,
                    }
                )
                next_version = version + 1
            else:  # EVENT_SOURCE_REVOKED
                if (
                    not entries
                    or version != entries[-1]["version"]
                    or public_key != entries[-1]["public_key"]
                ):
                    # Revocation pins the current key without adding one.
                    raise _Failure(ERR_INTEGRITY)
                revoked = True
        if not entries:
            # A registered source has no source_registered event.
            raise _Failure(ERR_INTEGRITY)
        if len(entries) != record["version"]:
            raise _Failure(ERR_INTEGRITY)
        if entries[-1]["public_key"] != record["public_key"]:
            raise _Failure(ERR_INTEGRITY)
        reconstructed[source] = entries
    return reconstructed

                if not entries or version != entries[-1]["version"]:
                    fail(
                        f"source {source!r} source_revoked event does not "
                        "match its current key version"
                    )
                if public_key != entries[-1]["public_key"]:
                    fail(
                        f"source {source!r} source_revoked event does not "
                        "match its current public key"
                    )
                revoked = True
        if not entries:
            fail(f"trust source {source!r} has no source_registered event")
        if len(entries) != record["version"]:
            fail(
                f"trust source {source!r} version {record['version']} does "
                f"not match {len(entries)} key lifecycle events"
            )
        if entries[-1]["public_key"] != record["public_key"]:
            fail(
                f"trust source {source!r} public key does not match its "
                "latest key lifecycle event"
            )
        reconstructed[source] = entries
    return reconstructed

def _parse_persisted_source_key_history(
    self,
    raw: object,
    trust_sources: dict[str, dict],
    audit_events: list[dict],
    path: str,
) -> tuple[dict[str, list[dict]], bool]:
    """Parse and cross-check the persisted per-source key history.

    Returns ``(history, needs_repair)``. A snapshot written before the
    feature (no ``source_key_history`` section) is accepted: the history is
    reconstructed in memory from the registry and the audit log and is
    naturally persisted by the next ordinary save — no migration write (and
    therefore no recovery-time generation bump) is forced. A present
    section is strictly validated structurally and must equal that
    reconstruction entry for entry; any discrepancy — malformed items,
    non-dense versions, wrong activation events or keys, or a registry
    source missing from the section — is snapshot corruption and raises
    StateRecoveryError, never silently rewritten. A history item whose
    source vanished from the registry is orphan data (exactly like a sync
    record whose source disappeared): it is pruned in memory rather than
    failing canonical-chain recovery.
    """

    def fail(reason: str) -> None:
        raise StateRecoveryError(path, reason)

    expected = self._reconstruct_source_key_history(
        trust_sources, audit_events, path
    )
    if raw is None:
        # Legacy snapshot: reconstruct in memory; the next ordinary save
        # persists it, so no migration write is forced on restart.
        return (
            {source: list(entries) for source, entries in expected.items()},
            False,
        )
    if not isinstance(raw, list):
        fail("'source_key_history' must be a list")
    history: dict[str, list[dict]] = {}
    for item in raw:
        if not isinstance(item, dict):
            fail("source_key_history entry must be an object")
        source = item.get("source")
        keys = item.get("keys")
        if not isinstance(source, str) or not source:
            fail("source_key_history entry needs a non-empty source")
        if source in history:
            fail(f"duplicate source_key_history for source {source!r}")
        if not isinstance(keys, list) or not keys:
            fail(f"source_key_history for {source!r} must be a non-empty list")
        entries: list[dict] = []
        for position, entry in enumerate(keys):
            if not isinstance(entry, dict) or set(entry) != {
                "version",
                "public_key",
                "activated_event_id",
            }:
                fail(
                    f"source_key_history item for {source!r} must contain "
                    "exactly version, public_key and activated_event_id"
                )
            version = entry["version"]
            public_key = entry["public_key"]
            activated = entry["activated_event_id"]
            if isinstance(version, bool) or not isinstance(version, int) or version < 1:
                fail(
                    f"source_key_history item for {source!r} needs a "
                    "positive integer version"
                )
            if version != position + 1:
                fail(
                    f"source_key_history versions for {source!r} must be "
                    "dense from 1"
                )
            if not crypto.is_hex64(public_key):
                fail(
                    f"source_key_history item for {source!r} public_key "
                    "must be 64 lowercase hex characters"
                )
            if isinstance(activated, bool) or not isinstance(activated, int) or activated < 0:
                fail(
                    f"source_key_history item for {source!r} "
                    "activated_event_id must be a non-negative integer"
                )
            if position > 0 and activated <= entries[-1]["activated_event_id"]:
                fail(
                    f"source_key_history activation ids for {source!r} "
                    "must be strictly ascending"
                )
            entries.append(
                {
                    "version": version,
                    "public_key": public_key,
                    "activated_event_id": activated,
                }
            )
        history[source] = entries
    # Cross-check against the registry + audit-log reconstruction.
    repaired = False
    for source in list(history):
        if source not in trust_sources:
            # The registry source vanished (the snapshot may have been
            # tampered by dropping a registry entry): its key history is
            # orphan data, pruned exactly like the source's sync records
            # rather than failing the canonical chain recovery.
            del history[source]
            repaired = True
            continue
        if history[source] != expected[source]:
            fail(
                f"source_key_history for {source!r} does not match its "
                "registry record and audit events"
            )
    for source, entries in expected.items():
        if source not in history:
            # Current code writes one history entry per registered source;
            # a present section missing a registry source is corruption
            # rather than a legacy migration.
            fail(f"source_key_history is missing source {source!r}")
    return history, repaired

@staticmethod
def _parse_persisted_allowlist(raw: object, path: str) -> dict[str, int]:
    """Strictly parse the keyless ``{source: expires_at}`` allowlist."""
    if raw is None:
        return {}
    if not isinstance(raw, dict):
        raise StateRecoveryError(path, "'allowlist' must be a JSON object")
    allowlist: dict[str, int] = {}
    for source, expires_at in raw.items():
        if not isinstance(source, str) or not source:
            raise StateRecoveryError(path, "allowlist source must be a non-empty string")
        if isinstance(expires_at, bool) or not isinstance(expires_at, int):
            raise StateRecoveryError(
                path, f"allowlist entry {source!r} expires_at must be an integer"
            )
        allowlist[source] = expires_at
    return allowlist

@staticmethod
def _parse_persisted_audit_events(raw: object, path: str) -> list[dict]:
    """Strictly parse the append-only audit event log.

    Every event is a JSON object carrying an integer ``at`` timestamp and a
    string ``kind``; ``event_id`` values must be exactly 1..N with no gaps
    or duplicates, since the id is the event's permanent audit position
    (which also fixes the log's total ordering). Payload fields beyond
    those three are retained verbatim.

    The historical sync lifecycle events additionally have their provenance
    metadata validated: ``sync_received`` / ``sync_adopted`` /
    ``sync_expired`` must carry a non-empty ``source`` and ``request_id``
    and a 64-char lowercase hex ``tip_hash``; an ``expires_at`` and the
    frozen tip summary (``height`` / ``length`` / ``status``) are checked
    when present — older snapshots' adopted events predate those fields, so
    missing ones are accepted but malformed ones are corruption. The
    keyless-allowlist events ``allowlist_added`` / ``allowlist_removed``
    likewise require a non-empty ``source`` and an integer
    ``expires_at``.
    """
    if raw is None:
        return []
    if not isinstance(raw, list):
        raise StateRecoveryError(path, "'audit_events' must be a list")
    sync_kinds = {
        EVENT_SYNC_RECEIVED,
        EVENT_SYNC_ADOPTED,
        EVENT_SYNC_EXPIRED,
    }
    allowlist_kinds = {
        EVENT_ALLOWLIST_ADDED,
        EVENT_ALLOWLIST_REMOVED,
    }
    events: list[dict] = []
    for i, event in enumerate(raw):
        if not isinstance(event, dict):
            raise StateRecoveryError(path, f"audit event {i + 1} must be an object")
        event_id = event.get("event_id")
        kind = event.get("kind")
        at = event.get("at")
        if (
            isinstance(event_id, bool)
            or not isinstance(event_id, int)
            or event_id != i + 1
        ):
            raise StateRecoveryError(
                path,
                f"audit event at position {i} has event_id {event_id!r}, "
                f"expected {i + 1}",
            )
        if not isinstance(kind, str) or not kind:
            raise StateRecoveryError(path, f"audit event {event_id} needs a kind")
        if isinstance(at, bool) or not isinstance(at, (int, float)):
            raise StateRecoveryError(path, f"audit event {event_id} needs a numeric 'at'")
        if kind in sync_kinds:
            source = event.get("source")
            request_id = event.get("request_id")
            tip_hash = event.get("tip_hash")
            if not isinstance(source, str) or not source:
                raise StateRecoveryError(
                    path, f"audit event {event_id} ({kind}) needs a source"
                )
            if not isinstance(request_id, str) or not request_id:
                raise StateRecoveryError(
                    path, f"audit event {event_id} ({kind}) needs a request_id"
                )
            if not crypto.is_hex64(tip_hash):
                raise StateRecoveryError(
                    path, f"audit event {event_id} ({kind}) has an invalid tip_hash"
                )
            expires_at = event.get("expires_at")
            if expires_at is not None and (
                isinstance(expires_at, bool) or not isinstance(expires_at, int)
            ):
                raise StateRecoveryError(
                    path,
                    f"audit event {event_id} ({kind}) expires_at must be an integer",
                )
            height = event.get("height")
            if height is not None and (
                isinstance(height, bool) or not isinstance(height, int) or height < 0
            ):
                raise StateRecoveryError(
                    path, f"audit event {event_id} ({kind}) has an invalid height"
                )
            length = event.get("length")
            if length is not None and (
                isinstance(length, bool) or not isinstance(length, int) or length < 1
            ):
                raise StateRecoveryError(
                    path, f"audit event {event_id} ({kind}) has an invalid length"
                )
            status = event.get("status")
            if status is not None and status not in (
                STATUS_PENDING,
                STATUS_CONFIRMED,
            ):
                raise StateRecoveryError(
                    path, f"audit event {event_id} ({kind}) has invalid status"
                )
            # The three frozen summary fields travel together: a partially
            # frozen event is an inconsistent write and is corruption.
            summary_fields = (height, length, status)
            if any(field is not None for field in summary_fields) and any(
                field is None for field in summary_fields
            ):
                raise StateRecoveryError(
                    path,
                    f"audit event {event_id} ({kind}) has a partial frozen summary",
                )
            # The attested-sync feature adds an optional mode; when present
            # it must be a recognized delivery mode.
            mode = event.get("mode")
            if mode is not None and mode not in (
                SYNC_MODE_PLAIN,
                SYNC_MODE_ATTESTED,
            ):
                raise StateRecoveryError(
                    path, f"audit event {event_id} ({kind}) has invalid mode"
                )
        elif kind in allowlist_kinds:
            # The keyless allowlist is authoritative configuration (exactly
            # like trust_sources): an allowlist_added/removed event must
            # carry a non-empty ``source`` and a plain (non-boolean)
            # integer ``expires_at``. A malformed payload is snapshot
            # corruption and fails recovery rather than loading.
            source = event.get("source")
            expires_at = event.get("expires_at")
            if not isinstance(source, str) or not source:
                raise StateRecoveryError(
                    path, f"audit event {event_id} ({kind}) needs a source"
                )
            if isinstance(expires_at, bool) or not isinstance(expires_at, int):
                raise StateRecoveryError(
                    path,
                    f"audit event {event_id} ({kind}) expires_at must be an integer",
                )
        events.append(dict(event))
    return events

def _parse_persisted_syncs(
    self,
    syncs_raw: object,
    forks: dict[str, list[Block]],
    canonical_chain: list[Block],
    trust_sources: dict[str, dict] | None = None,
) -> tuple[dict[tuple[str, str], dict], list[tuple[str, str, dict]], set[str]]:
    """Parse persisted PLAIN sync records, dropping unusable ones on restart.

    A record is kept only when it is structurally valid, has not yet
    expired, its source is still an active, unexpired entry of the
    persistent trust registry, and its tip references either a surviving
    candidate fork or a block on the canonical chain (a synced candidate
    may have been adopted). Records that expire while the process is down,
    or whose source is unknown/revoked/registry-expired, are pruned and
    additionally returned as ``expired_records`` (each as
    ``(source, request_id, {tip_hash, expires_at, fingerprint})``) so the
    caller backfills one sync_expired audit event per record — mirroring
    the runtime sweep. Other staleness (malformed structure, a record
    pointing at neither surviving location, or a fingerprint that no
    longer matches the delivered candidate) is a silent prune with no
    event; duplicated keys keep the first copy. Invalid records are
    silently dropped rather than failing recovery of the canonical chain.
    The historical sync_received/sync_adopted/sync_expired audit events
    are never touched by this pruning. Also returns the set of every tip
    any sync record claims provenance for (including dropped ones), so the
    caller can drop forks that only a pruned sync kept alive.
    """
    if not isinstance(syncs_raw, list):
        return {}, [], set()
    now = time.time()
    trust_sources = trust_sources or {}
    # Map every canonical block hash to the chain prefix ending there:
    # this is the exact "candidate" document that was delivered for a tip
    # since adopted onto the canonical chain.
    canonical_prefixes: dict[str, list[dict]] = {}
    prefix: list[dict] = []
    for block in canonical_chain:
        prefix = prefix + [block.to_dict()]
        canonical_prefixes[block.block_hash] = prefix
    syncs: dict[tuple[str, str], dict] = {}
    expired_records: list[tuple[str, str, dict]] = []
    synced_tips: set[str] = set()
    for rec_raw in syncs_raw:
        if not isinstance(rec_raw, dict):
            continue
        source = rec_raw.get("source")
        request_id = rec_raw.get("request_id")
        tip_hash = rec_raw.get("tip_hash")
        expires_at = rec_raw.get("expires_at")
        fingerprint = rec_raw.get("fingerprint")
        if not isinstance(source, str) or not source:
            continue
        if not isinstance(request_id, str) or not request_id:
            continue
        if not crypto.is_hex64(tip_hash):
            continue
        # The frozen tip summary is optional for snapshots written before
        # it was persisted; when present it must be structurally sound.
        frozen_height = rec_raw.get("height")
        frozen_length = rec_raw.get("length")
        frozen_status = rec_raw.get("status")
        if frozen_height is not None and (
            isinstance(frozen_height, bool)
            or not isinstance(frozen_height, int)
            or frozen_height < 0
        ):
            continue
        if frozen_length is not None and (
            isinstance(frozen_length, bool)
            or not isinstance(frozen_length, int)
            or frozen_length < 1
        ):
            continue
        if frozen_status is not None and frozen_status not in (
            STATUS_PENDING,
            STATUS_CONFIRMED,
        ):
            continue
        # Provenance is recorded even for dropped records: it proves the
        # matching fork must not outlive the sync that delivered it.
        synced_tips.add(tip_hash)
        record = {
            "tip_hash": tip_hash,
            "expires_at": expires_at,
            "fingerprint": fingerprint,
            "height": frozen_height,
            "length": frozen_length,
            "status": frozen_status,
        }
        if isinstance(expires_at, bool) or not isinstance(expires_at, int):
            # Malformed deadline: a structurally broken record, silently
            # pruned (no lifecycle event is attributable to it).
            continue
        expired_deadline = expires_at <= now
        # Re-authorization on restart: the trust decision recorded at
        # delivery is re-checked against the current registry. A source
        # rotated away, revoked or expired since then invalidates its
        # pending records; historical audit events stay queryable.
        trusted = trust_sources.get(source)
        auth_ok = (
            trusted is not None
            and trusted.get("status") == TRUST_ACTIVE
            and isinstance(trusted.get("expires_at"), int)
            and not isinstance(trusted.get("expires_at"), bool)
            and trusted["expires_at"] > now
        )
        if expired_deadline or not auth_ok:
            # Deadline elapsed or authorization lost while down: reconcile
            # exactly like the runtime sweep and backfill sync_expired,
            # regardless of the content fingerprint (the lifecycle event
            # is identified by source/request_id/tip/expires_at). Best
            # effort: freeze the summary from the surviving candidate when
            # the snapshot predates frozen summaries, so the backfilled
            # history row stays truthfully ordered.
            if frozen_height is None:
                descriptor = SyncSummary.from_locations(
                    tip_hash, forks, canonical_chain
                )
                if descriptor is not None:
                    record.update(descriptor)
            expired_records.append((source, request_id, record))
            continue
        if not isinstance(fingerprint, str) or not fingerprint:
            continue
        # An incremental range delivery additionally persists its
        # delivered {anchor, blocks} payload. Its fingerprint covers only
        # that payload (never the assembled prefix), so the record stays
        # re-verifiable independently of the current canonical chain:
        # validate the tail standalone, recompute the range fingerprint,
        # and confirm the resolved stored chain really is the canonical
        # prefix plus exactly that tail. A structurally malformed or
        # tampered range is a silent orphan prune with no event, exactly
        # like a full-sync fingerprint mismatch.
        range_raw = rec_raw.get("range")
        range_info: tuple[dict, list[dict], list[Block]] | None = None
        if range_raw is not None:
            range_info = self._parse_persisted_range(
                range_raw, tip_hash
            )
            if range_info is None:
                continue
        # Re-resolve the delivered candidate (a surviving fork, or the
        # canonical prefix for an adopted tip) and recompute its content
        # fingerprint: a tampered tip summary, deadline or request body
        # must not be trusted on the strength of the persisted record.
        blocks_raw: list[dict] | None = None
        surviving_fork = forks.get(tip_hash)
        if surviving_fork is not None:
            blocks_raw = [block.to_dict() for block in surviving_fork]
        else:
            blocks_raw = canonical_prefixes.get(tip_hash)
        if blocks_raw is None:
            continue
        if range_info is not None:
            range_anchor, range_blocks_raw, range_tail = range_info
            if self.range_fingerprint(range_anchor, range_tail) != fingerprint:
                continue
            anchor_height = range_anchor["height"]
            if len(blocks_raw) <= anchor_height + 1:
                continue
            stored_anchor = blocks_raw[anchor_height]
            tail_raw = blocks_raw[anchor_height + 1 :]
            if (
                stored_anchor.get("height") != anchor_height
                or stored_anchor.get("block_hash") != range_anchor["block_hash"]
                or tail_raw != range_blocks_raw
            ):
                continue
        elif self._candidate_fingerprint(blocks_raw) != fingerprint:
            continue
        # Verify the frozen summary metadata against the re-resolved
        # candidate: like a fingerprint mismatch, a tampered summary
        # invalidates the record silently (no lifecycle event), while a
        # legacy record without the frozen fields is repaired from the
        # candidate it references.
        descriptor = SyncSummary.from_blocks_raw(tip_hash, blocks_raw)
        if descriptor is None:
            continue
        if frozen_height is not None and (
            frozen_height != descriptor["height"]
            or frozen_length != descriptor["length"]
            or frozen_status != descriptor["status"]
        ):
            continue
        record.update(descriptor)
        if range_info is not None:
            # Retain the range payload so later saves and same-key retries
            # stay independent of the (possibly advanced) canonical chain.
            record["range"] = {
                "anchor": dict(range_info[0]),
                "blocks": range_info[1],
            }
        key = (source, request_id)
        if key in syncs:
            continue
        syncs[key] = record
    return syncs, expired_records, synced_tips

def _parse_persisted_attested_syncs(
    self,
    syncs_raw: object,
    forks: dict[str, list[Block]],
    canonical_chain: list[Block],
    trust_sources: dict[str, dict] | None = None,
    endowment: int = DEFAULT_INITIAL_BALANCE,
) -> tuple[dict[tuple[str, str], dict], list[tuple[str, str, dict]], set[str]]:
    """Parse persisted signature-ATTESTED sync records on restart.

    Mirrors :meth:`_parse_persisted_syncs` for the separate attested table
    and namespace. A kept record must be structurally sound, unexpired,
    its source still active/unexpired, and its signed candidate must (a)
    verify as an Ed25519 signature over SHA-256 of the canonical
    ``{domain, source, request_id, expires_at, candidate}`` message under
    the FROZEN key/version (a later rotation is not an authorization
    failure; only unknown/revoked/registry-expired sources are pruned), (b)
    recompute the stored fingerprint, and (c) re-validate as a chain
    byte-identical to the surviving stored fork (or canonical prefix, when
    adopted). Expiry or lost authorization is reconciled like plain sync
    (the returned records get a ``mode:"attested"`` sync_expired
    backfill); every other mismatch only drops the cached record — the
    canonical chain is untouched and the audit history stays continuous.
    Returns the same shapes as the plain parser.
    """
    if not isinstance(syncs_raw, list):
        return {}, [], set()
    now = time.time()
    trust_sources = trust_sources or {}
    canonical_prefixes: dict[str, list[dict]] = {}
    prefix: list[dict] = []
    for block in canonical_chain:
        prefix = prefix + [block.to_dict()]
        canonical_prefixes[block.block_hash] = prefix
    attested_syncs: dict[tuple[str, str], dict] = {}
    expired_records: list[tuple[str, str, dict]] = []
    synced_tips: set[str] = set()
    for rec_raw in syncs_raw:
        if not isinstance(rec_raw, dict):
            continue
        source = rec_raw.get("source")
        request_id = rec_raw.get("request_id")
        tip_hash = rec_raw.get("tip_hash")
        expires_at = rec_raw.get("expires_at")
        fingerprint = rec_raw.get("fingerprint")
        if not isinstance(source, str) or not source:
            continue
        if not isinstance(request_id, str) or not request_id:
            continue
        if not crypto.is_hex64(tip_hash):
            continue
        frozen_height = rec_raw.get("height")
        frozen_length = rec_raw.get("length")
        frozen_status = rec_raw.get("status")
        if frozen_height is not None and (
            isinstance(frozen_height, bool)
            or not isinstance(frozen_height, int)
            or frozen_height < 0
        ):
            continue
        if frozen_length is not None and (
            isinstance(frozen_length, bool)
            or not isinstance(frozen_length, int)
            or frozen_length < 1
        ):
            continue
        if frozen_status is not None and frozen_status not in (
            STATUS_PENDING,
            STATUS_CONFIRMED,
        ):
            continue
        # The frozen attestation is mandatory; any structural defect is a
        # cache mismatch → silent prune (no event, chain untouched).
        attested = self._parse_persisted_attestation(rec_raw)
        if attested is None:
            continue
        synced_tips.add(tip_hash)
        record = {
            "tip_hash": tip_hash,
            "expires_at": expires_at,
            "fingerprint": fingerprint,
            "height": frozen_height,
            "length": frozen_length,
            "status": frozen_status,
            "attested": attested,
        }
        if isinstance(expires_at, bool) or not isinstance(expires_at, int):
            continue
        expired_deadline = expires_at <= now
        trusted = trust_sources.get(source)
        auth_ok = (
            trusted is not None
            and trusted.get("status") == TRUST_ACTIVE
            and isinstance(trusted.get("expires_at"), int)
            and not isinstance(trusted.get("expires_at"), bool)
            and trusted["expires_at"] > now
        )
        if expired_deadline or not auth_ok:
            # Own deadline elapsed, or authorization lost while down:
            # reconcile exactly like the runtime sweep and backfill a
            # mode:"attested" sync_expired.
            if frozen_height is None:
                descriptor = SyncSummary.from_locations(
                    tip_hash, forks, canonical_chain
                )
                if descriptor is not None:
                    record.update(descriptor)
            expired_records.append((source, request_id, record))
